from collections import OrderedDict, deque
from bisect import bisect_left
import heapq
import math

def kelly(queries):
    lines = []
    for (probability, odds) in queries:
        if probability == 1:
            fraction = 1.0
        elif probability * odds <= 1 - probability:
            fraction = 0.0
        else:
            fraction = probability - (1 - probability) / odds
        lines.append(f'{fraction:.4f}')
    return lines

print(*kelly([(0.6, 1.0), (0.4, 1.0), (1.0, 0.01), (0.0, 2.0)]), sep='\n')
